"""Bring up robot_state_publisher, joint_state_publisher and move_group
for the simple 3-joint revolute arm, loading all config straight from
files on disk (this directory is a plain folder, not an installed
ament package, so we build the parameter dictionaries by hand instead
of using MoveItConfigsBuilder)."""

import os
import yaml

from launch import LaunchDescription
from launch_ros.actions import Node

THIS_DIR = os.path.dirname(os.path.abspath(__file__))
BASE_DIR = os.path.dirname(THIS_DIR)


def load_file(path):
    with open(path, "r") as f:
        return f.read()


def load_yaml(path):
    with open(path, "r") as f:
        return yaml.safe_load(f)


def generate_launch_description():
    urdf_path = os.path.join(BASE_DIR, "urdf", "arm.urdf")
    srdf_path = os.path.join(BASE_DIR, "config", "arm.srdf")
    kinematics_path = os.path.join(BASE_DIR, "config", "kinematics.yaml")
    joint_limits_path = os.path.join(BASE_DIR, "config", "joint_limits.yaml")
    ompl_planning_path = os.path.join(BASE_DIR, "config", "ompl_planning.yaml")

    robot_description = {"robot_description": load_file(urdf_path)}
    robot_description_semantic = {
        "robot_description_semantic": load_file(srdf_path)
    }
    robot_description_kinematics = {
        "robot_description_kinematics": load_yaml(kinematics_path)
    }
    robot_description_planning = {
        "robot_description_planning": load_yaml(joint_limits_path)
    }

    ompl_planning_pipeline_config = {
        "planning_pipelines": ["ompl"],
        "default_planning_pipeline": "ompl",
        "ompl": load_yaml(ompl_planning_path),
    }

    planning_scene_monitor_config = {
        "publish_planning_scene": True,
        "publish_geometry_updates": True,
        "publish_state_updates": True,
        "publish_transforms_updates": True,
    }

    robot_state_publisher_node = Node(
        package="robot_state_publisher",
        executable="robot_state_publisher",
        name="robot_state_publisher",
        output="log",
        parameters=[robot_description],
    )

    joint_state_publisher_node = Node(
        package="joint_state_publisher",
        executable="joint_state_publisher",
